import{_ as n,o as t,c as r,a3 as a}from"./chunks/framework.B9qR_F1m.js";const i="/bilder/uebersicht.jpg",p=JSON.parse('{"title":"Übersicht","description":"","frontmatter":{},"headers":[],"relativePath":"bereiche/uebersicht.md","filePath":"bereiche/uebersicht.md"}'),s={name:"bereiche/uebersicht.md"};function l(d,e,o,h,g,u){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="ubersicht" tabindex="-1">Übersicht <a class="header-anchor" href="#ubersicht" aria-label="Permalink to &quot;Übersicht&quot;">​</a></h1><p>Die Übersicht ist der Leitstand für das ganze Paket: alle Flights mit ihrem Stand, was noch zu prüfen ist, wer was darf, und die Unterlagen zum Herunterladen.</p><p><img src="'+i+'" alt="Bereich Übersicht mit Prüfungen und Freigaben eines Flights" loading="lazy"></p><h2 id="links-phase-und-paket" tabindex="-1">Links: Phase und Paket <a class="header-anchor" href="#links-phase-und-paket" aria-label="Permalink to &quot;Links: Phase und Paket&quot;">​</a></h2><p><strong>Phase</strong> – nur beim gemeinsamen Planen wichtig:</p><table tabindex="0"><thead><tr><th>Phase</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Entwurf</strong></td><td>Nur der Designer plant. Piloten sehen schon, ändern aber nichts.</td></tr><tr><td><strong>Planung</strong></td><td>Flights arbeiten im Rahmen ihrer Freigaben.</td></tr><tr><td><strong>Eingefroren</strong></td><td>Keine Änderungen mehr durch Flights – z. B. kurz vor dem Briefing.</td></tr></tbody></table><p>Darunter <strong>Paket</strong>: alle spielbaren Flights mit Typ, Aufgabe, Frequenz, Startzeit und Beladung in einer Zeile. Ein rotes <strong>prüfen</strong> zeigt, dass Shardwing etwas gefunden hat; <strong>Hinweise</strong> sind weniger dringend.</p><p>Ganz oben steht der Eintrag <strong>Paket</strong> selbst – dort findest du Server-Links, Downloads für alle, Intel für alle, Wetter und Callsigns.</p><h2 id="rechts-details-eines-flights" tabindex="-1">Rechts: Details eines Flights <a class="header-anchor" href="#rechts-details-eines-flights" aria-label="Permalink to &quot;Rechts: Details eines Flights&quot;">​</a></h2><p>Klick einen Flight an:</p><h3 id="prufungen" tabindex="-1">Prüfungen <a class="header-anchor" href="#prufungen" aria-label="Permalink to &quot;Prüfungen&quot;">​</a></h3><p>Shardwing schaut automatisch nach typischen Fehlern. Zum Beispiel:</p><ul><li>Gleiche Frequenz wie ein anderer Flight</li><li>Joker/Bingo fehlen auf der Lineup Card</li><li>Keine Cartridge – der Jet startet mit der Missionsroute</li><li>Laser-Code auch bei einem anderen Flight</li><li>Timing: laut Route zu früh oder zu spät am Zielpunkt, lange Wartezeit vor Beginn</li><li>Deconfliction: Annäherung an einen anderen Flight</li><li>Comm Plan: Kanäle in der Cartridge weichen ab</li><li>Threats nur für diesen Flight – Hinweis, Unterlagen per Export zu verteilen, damit andere Flights desselben Typs sie nicht im Kneeboard sehen</li></ul><p>Steht dort <strong>Keine Auffälligkeiten.</strong>, ist der Flight sauber.</p><h3 id="freigaben" tabindex="-1">Freigaben <a class="header-anchor" href="#freigaben" aria-label="Permalink to &quot;Freigaben&quot;">​</a></h3><p>Eine Matrix, was <strong>Lead</strong> und <strong>Wingman</strong> dieses Flights beim gemeinsamen Planen ändern dürfen: Route &amp; Steerpoints, Funk-Presets, CMDS, Lineup Card, eigene Threats, Beladung. Mit <strong>Ansicht als Lead</strong> / <strong>als Wingman</strong> prüfst du das direkt. (<a href="/gemeinsam/rollen">Rollen und Freigaben</a>)</p><h3 id="intel" tabindex="-1">Intel <a class="header-anchor" href="#intel" aria-label="Permalink to &quot;Intel&quot;">​</a></h3><p>Wie viele Bedrohungen der Flight kennt, getrennt nach „für alle“ und „nur für diesen Flight“ – als Anzahl × Typ, ohne Gruppennamen.</p><h3 id="lineup-card-·-kneeboard" tabindex="-1">Lineup Card · Kneeboard <a class="header-anchor" href="#lineup-card-·-kneeboard" aria-label="Permalink to &quot;Lineup Card · Kneeboard&quot;">​</a></h3><p>Die fertigen Seiten des Flights als Vorschau, mit Sprung in den Editor.</p><h3 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads&quot;">​</a></h3><p><strong>PDF</strong> und <strong>Kneeboard-ZIP</strong> für genau diesen Flight. Praktisch, um einem Piloten seine Unterlagen zu schicken.</p><h2 id="wetter" tabindex="-1">Wetter <a class="header-anchor" href="#wetter" aria-label="Permalink to &quot;Wetter&quot;">​</a></h2><p>Für das Paket zeigt Shardwing das Missionswetter als <strong>METAR</strong> je Flugplatz – Wind am Boden und in der Höhe, QNH, Temperatur, Sicht, Wolken. Mit <strong>+ Flugplatz</strong> fügst du weitere Plätze hinzu, z. B. Diverts.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Der METAR wird aus den Wettereinstellungen der Mission berechnet. Ungewöhnliche Wolken-Presets aus Mods kennt Shardwing nicht immer; dann steht „unbekannt“ daneben.</p></div><h2 id="callsigns-aufgaben" tabindex="-1">Callsigns &amp; Aufgaben <a class="header-anchor" href="#callsigns-aufgaben" aria-label="Permalink to &quot;Callsigns &amp; Aufgaben&quot;">​</a></h2><p>DCS-Callsigns wie „Enfield 1“ sind oft nicht das, was eine Staffel funkt. In dieser Tabelle gibst du jedem Flight:</p><ul><li>einen <strong>eigenen Callsign</strong> mit Nummer (z. B. VIPER 1) – mit <strong>Vorschlägen</strong> passend zur Rolle, schon vergebene ausgeblendet,</li><li>eine <strong>Aufgabe</strong> und Zweitaufgabe (SWEEP, ESCORT, BARCAP, TARCAP, STRIKE, CAS, SEAD, DEAD, AR, AEW …).</li></ul><p><strong>Favoriten vergeben</strong> und <strong>Durchnummerieren</strong> helfen bei großen Paketen. Die Namen erscheinen auf allen Unterlagen; Gruppennamen und DCS-Callsigns in der .miz bleiben unverändert.</p>',29)])])}const b=n(s,[["render",l]]);export{p as __pageData,b as default};
